mapper.select:
select s.id, s.name, s.price, s.status, s.description, s.image, s.update_time, c.name as categoryName
from setmeal s left join category c on s.category_id = c.id


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}

select s.id, s.category_id,s.name, s.price, s.status, s.description, s.image, s.update_time, c.name as categoryName
from setmeal s left join category c on s.category_id = c.id
where s.id = #{id}

select sd.id, sd.setmeal_id, sd.dish_id, sd.name, sd.price, sd.copies
from setmeal_dish sd
where sd.setmeal_id = #{id}
